<script setup lang="ts">import {ref} from 'vue';import {Camera,Star,Archive,Check} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {useSelectedVehicle} from '../composables/useSelectedVehicle';import {useVintro} from '../composables/useVintro';const {vehicle,base}=useSelectedVehicle();const {state,setPrimaryVehicle,updateVehicle}=useVintro();const form=ref({registration:vehicle.value.registration??'',mileage:vehicle.value.mileage,status:vehicle.value.ownershipStatus,since:vehicle.value.ownershipSince});const imageName=ref('');const save=()=>updateVehicle(vehicle.value.id,{registration:form.value.registration,mileage:Number(form.value.mileage),ownershipStatus:form.value.status as 'Current'|'Previous',ownershipSince:form.value.since});const chooseImage=(event:Event)=>{const file=(event.target as HTMLInputElement).files?.[0];if(file){imageName.value=file.name;updateVehicle(vehicle.value.id,{image:URL.createObjectURL(file)})}}
</script>
<template><PageHeader title="Manage vehicle" :back="base"/><form @submit.prevent="save" class="container-app max-w-3xl py-7"><div class="relative h-56 overflow-hidden rounded-3xl bg-stone-200"><img :src="vehicle.image" class="h-full w-full object-cover"/><label class="absolute bottom-4 right-4 flex cursor-pointer items-center gap-2 rounded-xl bg-white px-4 py-3 text-sm font-semibold shadow"><Camera :size="17"/>Change image<input type="file" accept="image/*" class="sr-only" @change="chooseImage"/></label></div><p v-if="imageName" class="mt-2 text-xs text-muted">Selected {{imageName}}</p><h1 class="page-title mt-7">{{vehicle.make}} {{vehicle.model}}</h1><section class="card mt-6 p-5"><h2 class="section-title">Vehicle details</h2><div class="mt-5 grid gap-5 sm:grid-cols-2"><label><span class="label">Registration number</span><input v-model="form.registration" class="field uppercase"/></label><label><span class="label">Current mileage</span><input v-model="form.mileage" type="number" class="field nums"/></label><label><span class="label">Ownership status</span><select v-model="form.status" class="field"><option>Current</option><option>Previous</option></select></label><label><span class="label">Ownership dates</span><input v-model="form.since" class="field"/></label></div></section><button v-if="state.primaryVehicleId!==vehicle.id" type="button" @click="setPrimaryVehicle(vehicle.id)" class="btn-secondary mt-5 w-full"><Star :size="17"/>Set as primary vehicle</button><div v-else class="mt-5 flex items-center gap-2 rounded-xl bg-emerald-50 p-4 text-sm font-semibold text-success"><Star :size="17" fill="currentColor"/>This is your primary vehicle</div><button class="btn-primary mt-5 w-full"><Check :size="17"/>Save vehicle</button><button type="button" @click="form.status='Previous'" class="mt-4 flex w-full items-center justify-center gap-2 py-3 text-sm font-semibold text-muted"><Archive :size="17"/>Move to previous vehicles</button></form></template>
